```python
import jsonschema

# Define the registry of meta-schemas and vocabularies
registry = {
    'meta_schema1': {
        'id': 'http://example.com/meta-schema1',
        'schema': {
            'type': 'object',
            'properties': {
                'name': {'type': 'string'},
                'age': {'type': 'integer'}
            }
        }
    },
    'meta_schema2': {
        'id': 'http://example.com/meta-schema2',
        'schema': {
            'type': 'object',
            'properties': {
                'color': {'type': 'string'},
                'shape': {'type': 'string'}
            }
        }
    }
}

# Function to retrieve a meta-schema by its ID
def get_meta_schema(schema_id):
    if schema_id in registry:
        return registry[schema_id]['schema']
    else:
        raise ValueError(f"Meta-schema '{schema_id}' not found in the registry")

# Function to validate a JSON document against a meta-schema
def validate_document(document, meta_schema_id):
    meta_schema = get_meta_schema(meta_schema_id)
    try:
        jsonschema.validate(instance=document, schema=meta_schema)
        print("Document is valid according to the specified meta-schema.")
    except jsonschema.exceptions.ValidationError as e:
        print(f"Document is not valid: {e}")

# Example usage
document = {
    'name': 'John',
    'age': 30,
    'color': 'red',
    'shape': 'circle'
}

validate_document(document, 'meta_schema1')
```

