```python
import os

class Path:
    def __init__(self, *components):
        self.components = components

    def join(self, *other_components):
        return Path(*(self.components + other_components))

    def separate(self):
        return self.components

    def normalize(self):
        return os.path.normpath("/".join(self.components))

    def __str__(self):
        return "/".join(self.components)
```

You can use this class to create paths, join them, separate them, normalize them, and print them in a human-readable format. For example:

```python
path = Path("home", "user", "documents")
joined_path = path.join("projects", "project1")
separated_components = path.separate()
normalized_path = path.normalize()
print(path)  # Output: home/user/documents
print(joined_path)  # Output: home/user/documents/projects/project1
print(separated_components)  # Output: ['home', 'user', 'documents']
print(normalized_path)  # Output: /home/user/documents
```

