```python
from typing import Callable, Any, Iterable, TypeVar, List, Optional
from collections import deque
from collections.abc import Generator

T = TypeVar('T')
U = TypeVar('U')

class Observer:
    def __init__(self):
        self._queue = deque()

    def next(self, value: T) -> None:
        self._queue.append(value)

    def complete(self) -> None:
        self._queue.append(None)

    def error(self, exception: Exception) -> None:
        self._queue.append(exception)

    def get_next(self) -> T:
        return self._queue.popleft()

class Observable:
    def __init__(self, source: Callable[[], Generator[T, None, None]]):
        self._source = source

    def subscribe(self, observer: Observer) -> None:
        try:
            for value in self._source():
                observer.next(value)
        except Exception as e:
            observer.error(e)
        finally:
            observer.complete()

def from_iterable(iterable: Iterable[T]) -> Observable[T]:
    def source() -> Generator[T, None, None]:
        for item in iterable:
            yield item
    return Observable(source)

def map_(self: Observable[T], transform: Callable[[T], U]) -> Observable[U]:
    def source() -> Generator[U, None, None]:
        for value in self._source():
            yield transform(value)
    return Observable(source)

Observable.map = map_

# Example usage
def main():
    source = from_iterable([1, 2, 3, 4, 5])
    observer = Observer()
    source.subscribe(observer)

    while True:
        try:
            value = observer.get_next()
            if value is None:
                break
            print(value)
        except Exception as e:
            print(f"Error: {e}")
            break

if __name__ == "__main__":
    main()
```

This example provides a simple implementation of an observable and observer, along with a basic `map_` operator to transform values emitted by an observable. The `from_iterable` function allows creating an observable from an iterable collection.

You can use this library to create reactive streams and manage events in a declarative manner, similar to ReactiveX (Rx) for Python. Feel free to extend and customize this implementation according to your specific needs.

