```python
from flask import Flask, render_template, request, redirect, url_for
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)

@app.route('/')
def index():
    users = User.query.all()
    return render_template('index.html', users=users)

@app.route('/create', methods=['GET', 'POST'])
def create():
    if request.method == 'POST':
        username = request.form['username']
        email = request.form['email']
        user = User(username=username, email=email)
        db.session.add(user)
        db.session.commit()
        return redirect(url_for('index'))
    return render_template('create.html')

@app.route('/update/<int:id>', methods=['GET', 'POST'])
def update(id):
    user = User.query.get(id)
    if request.method == 'POST':
        user.username = request.form['username']
        user.email = request.form['email']
        db.session.commit()
        return redirect(url_for('index'))
    return render_template('update.html', user=user)

@app.route('/delete/<int:id>')
def delete(id):
    user = User.query.get(id)
    db.session.delete(user)
    db.session.commit()
    return redirect(url_for('index'))

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
```

In this example, we're using the Flask framework and SQLAlchemy as the ORM for the database. The `User` model represents the user table in the database, with columns for `id`, `username`, and `email`.

The `index` route retrieves all users from the database and passes them to the `index.html` template for rendering.

The `create` route handles the creation of a new user. If the request method is POST, it retrieves the username and email from the form data, creates a new `User` instance, adds it to the database session, and commits the changes.

The `update` route handles the update of an existing user. If the request method is POST, it retrieves the updated username and email from the form data, updates the corresponding `User` instance in the database session, and commits the changes.

The `delete` route handles the deletion of a user by retrieving the user from the database, deleting it from the database session, and committing the changes.

Remember to create the `index.html`, `create.html`, and `update.html` templates in a `templates` directory in the same directory as your Python script.

You can run this application by executing the Python script. It will create the database if it doesn't exist, and you can access the web application at `http://localhost:5000`.

Certainly! Below is an example of a comprehensive project management system in Python using the Flask web framework, SQLAlchemy for database management, and Bootstrap for frontend styling. This system includes task tracking, team collaboration, and progress reporting.

```python
from flask import Flask, render_template, request, redirect, url_for
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///projects.db'
db = SQLAlchemy(app)

class Project(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    description = db.Column(db.Text, nullable=True)
    start_date = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    end_date = db.Column(db.DateTime, nullable=True)
    tasks = db.relationship('Task', backref='project', lazy=True)

class Task(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    description = db.Column(db.Text, nullable=True)
    completed = db.Column(db.Boolean, default=False)
    deadline = db.Column(db.DateTime, nullable=True)
    project_id = db.Column(db.Integer, db.ForeignKey('project.id'), nullable=False)

@app.route('/')
def index():
    projects = Project.query.all()
    return render_template('index.html', projects=projects)

@app.route('/add_project', methods=['GET', 'POST'])
def add_project():
    if request.method == 'POST':
        name = request.form['name']
        description = request.form['description']
        project = Project(name=name, description=description)
        db.session.add(project)
        db.session.commit()
        return redirect(url_for('index'))
    return render_template('add_project.html')

@app.route('/add_task/<int:project_id>', methods=['GET', 'POST'])
def add_task(project_id):
    project = Project.query.get_or_404(project_id)
    if request.method == 'POST':
        name = request.form['name']
        description = request.form['description']
        deadline = datetime.strptime(request.form['deadline'], '%Y-%m-%d')
        task = Task(name=name, description=description, deadline=deadline, project=project)
        db.session.add(task)
        db.session.commit()
        return redirect(url_for('view_project', project_id=project_id))
    return render_template('add_task.html', project=project)

@app.route('/view_project/<int:project_id>')
def view_project(project_id):
    project = Project.query.get_or_404(project_id)
    tasks = Task.query.filter_by(project_id=project_id).all()
    return render_template('view_project.html', project=project, tasks=tasks)

if __name__ == '__main__':
    app.run(debug=True)
```

