import axios from 'axios'

export async function getRunStatus(runId: string): Promise<string> {
  try {
    const response = await axios.get(`/runs/${runId}/status`)
    return response.data.status
  } catch (error) {
    return 'Error fetching run status'
  }
}

describe('RunStatusService', () => {
  afterEach(() => {
    jest.clearAllMocks()
  })

  it('should get run status successfully', async () => {
    jest.spyOn(axios, 'get').mockImplementationOnce(() => {
      return Promise.resolve({
        data: {
          status: 'completed'
        }
      })
    })

    const runId = '123'
    const status = await getRunStatus(runId)

    expect(status).toBe('completed')
    expect(axios.get).toHaveBeenCalledWith(`/runs/${runId}/status`)
  })

  it('should return error message for failed status fetch', async () => {
    jest.spyOn(axios, 'get').mockImplementationOnce(() => {
      return Promise.reject(new Error('Network error'))
    })

    const runId = '123'
    const status = await getRunStatus(runId)

    expect(status).toBe('Error fetching run status')
    expect(axios.get).toHaveBeenCalledWith(`/runs/${runId}/status`)
  })
})

// Test case to verify the getRunStatus function
test('getRunStatus returns the correct status', async () => {
  // Mock the axios.get function to return a resolved promise with a status of 'completed'
  jest.spyOn(axios, 'get').mockResolvedValue({
    data: { status: 'completed' }
  })

  // Call the getRunStatus function with a runId of '123'
  const status = await getRunStatus('123')

  // Expect the status to be 'completed'
  expect(status).toBe('completed')
})

// Test case to verify the error handling of the getRunStatus function
test('getRunStatus handles network errors', async () => {
  // Mock the axios.get function to return a rejected promise with an error message of 'Network error'
  jest.spyOn(axios, 'get').mockRejectedValue(new Error('Network error'))

  // Call the getRunStatus function with a runId of '123'
  const status = await getRunStatus('123')

  // Expect the status to be 'Error fetching run status'
  expect(status).toBe('Error fetching run status')
})

// Test case to verify the error handling of the getRunStatus function when the response status is not 200
test('getRunStatus handles non-200 status', async () => {
  // Mock the axios.get function to return a resolved promise with a status of 404
  jest.spyOn(axios, 'get').mockResolvedValue({
    data: { status: 'not found' },
    status: 404
  })

  // Call the getRunStatus function with a runId of '123'
  const status = await getRunStatus('123')

  // Expect the status to be 'Error fetching run status'
  expect(status).toBe('Error fetching run status')
})

// Test case to verify the error handling of the getRunStatus function when the response is not an object
test('getRunStatus handles non-object response', async () => {
  // Mock the axios.get function to return a resolved promise with a response that is not an object
  jest.spyOn(axios, 'get').mockResolvedValue({
    data: 'not an object',
    status: 200
  })

  // Call the getRunStatus function with a runId of '123'
  const status = await getRunStatus('123')

  // Expect the status to be 'Error fetching run status'
  expect(status).toBe('Error fetching run status')
})

// Test case to verify the error handling of the getRunStatus function when the response data is not an object
test('getRunStatus handles non-object response data', async () => {
  // Mock the axios.get function to return a resolved promise with a response that has a data property that is not an object
  jest.spyOn(axios, 'get').mockResolvedValue({
    data: { status: 'not an object' },
    status: 200
  })

  // Call the getRunStatus function with a runId of '123'
  const status = await getRunStatus('123')

  // Expect the status to be 'Error fetching run status'
  expect(status).toBe('Error fetching run status')
