```python
import jupyter

class NotebookCache:
    def __init__(self):
        self.cache = {}

    def add_notebook(self, notebook_path):
        # Add the notebook path to the cache
        self.cache[notebook_path] = True

    def get_notebook(self, notebook_path):
        # Check if the notebook is in the cache
        if notebook_path in self.cache:
            return True
        else:
            return False

    def remove_notebook(self, notebook_path):
        # Remove the notebook path from the cache
        if notebook_path in self.cache:
            del self.cache[notebook_path]
            return True
        else:
            return False

# Example usage
cache = NotebookCache()
cache.add_notebook("path/to/notebook1.ipynb")
cache.add_notebook("path/to/notebook2.ipynb")

print(cache.get_notebook("path/to/notebook1.ipynb"))  # Output: True
print(cache.get_notebook("path/to/notebook3.ipynb"))  # Output: False

cache.remove_notebook("path/to/notebook2.ipynb")

print(cache.get_notebook("path/to/notebook2.ipynb"))  # Output: False
```

