import boto3
from botocore.exceptions import ClientError

def handle_error(func):
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except ClientError as e:
            error_message = f"An error occurred: {e.response['Error']['Message']}"
            raise Exception(error_message) from e
    return wrapper

# Wrap boto3 methods with error handling functions
ec2 = boto3.client('ec2')
def create_instance():
    instance = ec2.run_instances(ImageId='ami-0abcdef1234567890', MinCount=1, MaxCount=1)
    return instance

def get_instance_status(instance_id):
    try:
        return ec2.describe_instances(InstanceIds=[instance_id])['Reservations'][0]['Instances'][0]['State']['Name']
    except ClientError as e:
        error_message = f"An error occurred: {e.response['Error']['Message']}"
        raise Exception(error_message) from e

# Usage
try:
    instance = create_instance()
    instance_id = instance['Instances'][0]['InstanceId']
    print(f"Instance created: {instance_id}")
    status = get_instance_status(instance_id)
    print(f"Instance status: {status}")
except Exception as e:
    print(e)
```
This code imports the necessary modules, defines an error handling function `handle_error`, wraps boto3 methods with that function to handle errors, and provides meaningful error messages.
