```python
import pytest
import threading
import doctest
import unittest
import logging

class AdvancedDoctestPlugin(pytest.Plugin):
    def __init__(self):
        self.doctests = []

    def pytest_pycollect_makeitem(self, collector, name, obj):
        if collector.name == "doctest":
            self.doctests.append(name)

    def pytest_pycollect_makeitemcol(self, collector, name, obj):
        if collector.name == "doctest":
            self.doctests.append(name)

    def pytest_collectreport(self, collector, report):
        if collector.name == "doctest":
