Certainly! Below is an example of a basic relational programming system implemented in Python. This system allows users to define tables, establish relationships between them, and execute queries.

```python
class Table:
    def __init__(self, name, columns):
        self.name = name
        self.columns = columns
        self.rows = []

    def insert_row(self, row):
        self.rows.append(row)

    def select(self, column):
        return [row[column] for row in self.rows]

    def join(self, other_table, left_on, right_on):
        return [(row, other_row) for row in self.rows for other_row in other_table.rows if row[left_on] == other_row[right_on]]

class RelationalProgrammingSystem:
    def __init__(self):
        self.tables = {}

    def create_table(self, name, columns):
        self.tables[name] = Table(name, columns)

    def insert_row(self, table_name, row):
        self.tables[table_name].insert_row(row)

    def select(self, table_name, column):
        return self.tables[table_name].select(column)

    def join(self, table_name1, table_name2, left_on, right_on):
        table1 = self.tables[table_name1]
        table2 = self.tables[table_name2]
        return table1.join(table2, left_on, right_on)

# Example usage
rps = RelationalProgrammingSystem()

# Create tables
rps.create_table('users', ['id', 'name', 'email'])
rps.create_table('orders', ['id', 'user_id', 'product', 'quantity'])

# Insert rows
rps.insert_row('users', [1, 'John Doe', 'john@example.com'])
rps.insert_row('users', [2, 'Jane Smith', 'jane@example.com'])
rps.insert_row('orders', [1, 1, 'Widget', 2])
rps.insert_row('orders', [2, 2, 'Gadget', 1])

# Select columns
print(rps.select('users', 'name'))  # Output: ['John Doe', 'Jane Smith']

# Join tables
joined_data = rps.join('users', 'orders', 'id', 'user_id')
for user, order in joined_data:
    print(f"User: {user['name']}, Order: {order['product']}")

# Output:
# User: John Doe, Order: Widget
# User: Jane Smith, Order: Gadget
```

This example demonstrates how to create tables, insert rows, select specific columns, and perform joins between tables. You can expand this system by adding more features like updating rows, deleting rows, or creating more complex queries.

