```python
import json
import requests
from requests.auth import HTTPBasicAuth

class SalesforceAPI:
    def __init__(self, username, password, security_token, instance_url):
        self.username = username
        self.password = password
        self.security_token = security_token
        self.instance_url = instance_url
        self.session_id = None

    def login(self):
        url = f"{self.instance_url}/services/Soap/u/45.0"
        headers = {'Content-Type': 'text/xml'}
        payload = f"""
        <soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:urn="urn:partner.soap.sforce.com">
           <soapenv:Header>
              <urn:CallOptions>
                 <urn:client>PythonAPI</urn:client>
              </urn:CallOptions>
           </soapenv:Header>
           <soapenv:Body>
              <urn:login>
                 <urn:username>{self.username}</urn:username>
                 <urn:password>{self.password}{self.security_token}</urn:password>
              </urn:login>
           </soapenv:Body>
        </soapenv:Envelope>
        """
        response = requests.post(url, headers=headers, data=payload)
        if response.status_code == 200:
            response_json = json.loads(response.text)
            self.session_id = response_json['loginResponse']['result']['sessionId']
            print("Logged in successfully!")
        else:
            print("Failed to login.")

    def create_record(self, object_name, fields):
        if not self.session_id:
            print("Not logged in. Please call login() first.")
            return

        url = f"{self.instance_url}/services/data/v45.0/sobjects/{object_name}/"
        headers = {
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {self.session_id}'
        }
        payload = {
            'fields': fields
        }
        response = requests.post(url, headers=headers, data=json.dumps(payload))
        if response.status_code == 201:
            print("Record created successfully!")
        else:
            print("Failed to create record.")

    def update_record(self, object_name, record_id, fields):
        if not self.session_id:
            print("Not logged in. Please call login() first.")
            return

        url = f"{self.instance_url}/services/data/v45.0/sobjects/{object_name}/{record_id}"
        headers = {
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {self.session_id}'
        }
        payload = {
            'fields': fields
        }
        response = requests.patch(url, headers=headers, data=json.dumps(payload))
        if response.status_code == 204:
            print("Record updated successfully!")
        else:
            print("Failed to update record.")

    def search_records(self, object_name, query):
        if not self.session_id:
            print("Not logged in. Please call login() first.")
            return

        url = f"{self.instance_url}/services/data/v45.0/query?q={query}"
        headers = {
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {self.session_id}'
        }
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            print("Records found:")
            print(response.json())
        else:
            print("Failed to search records.")
```

This class includes methods for logging in, creating, updating, and searching records within a Salesforce instance. Please ensure you have the necessary credentials and instance URL when creating an instance of the `SalesforceAPI` class.

