```python
import subprocess

class CpuSet:
    def __init__(self, name):
        self.name = name

    def set(self, cpus):
        command = ['taskset', '-c', cpus, 'self']
        subprocess.run(command)

    def unset(self):
        command = ['taskset', '-c', '0', 'self']
        subprocess.run(command)

    def list(self):
        command = ['taskset', '-c', 'self']
        result = subprocess.run(command, capture_output=True, text=True)
        return result.stdout.strip()
