class SortedList(list):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.sort()

    def add(self, item):
        super().append(item)
        self.sort()

    def remove(self, item):
        super().remove(item)

    def search(self, item):
        index = bisect.bisect_left(self, item)
        if index < len(self) and self[index] == item:
            return index
        return -1

class SearchDict(dict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def search(self, key):
        return self.get(key)

class FormattedString(str):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def format(self, *args, **kwargs):
        return super().format(*args, **kwargs)
```

In this example, we create subclasses for `list`, `dict`, and `str` with additional functionality and convenience methods. The `SortedList` class sorts the list when it is initialized and provides additional methods for adding, removing, and searching items. The `SearchDict` class provides a `search` method to search for keys in the dictionary. The `FormattedString` class provides a `format` method to format the string using the same syntax as the `str.format` method.

